package br.com.serviceflow.api.service;
import br.com.serviceflow.api.dto.auth.*; import br.com.serviceflow.api.repository.UsuarioRepository; import java.time.LocalDateTime; import org.springframework.beans.factory.annotation.Value; import org.springframework.mail.SimpleMailMessage; import org.springframework.mail.javamail.JavaMailSender; import org.springframework.stereotype.Service;
@Service public class SupportRecoveryService {
 private final UsuarioRepository users; private final JavaMailSender mail; private final String supportEmail,from;
 public SupportRecoveryService(UsuarioRepository users,JavaMailSender mail,@Value("${app.support.email:}") String supportEmail,@Value("${spring.mail.username:}") String from){this.users=users;this.mail=mail;this.supportEmail=supportEmail;this.from=from;}
 public MessageResponse request(ForgotPasswordRequest x){users.findByEmailIgnoreCase(x.email()).ifPresent(u->{if(supportEmail.isBlank())throw new IllegalStateException("SUPPORT_EMAIL não configurado");SimpleMailMessage m=new SimpleMailMessage();m.setFrom(from);m.setTo(supportEmail);m.setSubject("ServiceFlow - solicitação de nova senha");m.setText("Usuário: "+u.getNome()+"\nE-mail: "+u.getEmail()+"\nData: "+LocalDateTime.now()+"\n\nConfirme a identidade antes de redefinir o acesso.");mail.send(m);});return new MessageResponse("Se o e-mail estiver cadastrado, a solicitação será encaminhada ao suporte",null);}
}
